"use client";

/**
 * Debounced Street-address autocomplete, wired to /api/geoapify/autocomplete.
 * Only ever mounted when the server already confirmed GEOAPIFY_API_KEY is set
 * (components/customer/DomainRegisterWizard.tsx's `geoapifyEnabled` prop) — this
 * component assumes the endpoint is live and simply degrades to "no dropdown"
 * on a transient failure, it never has to decide whether the feature exists.
 *
 * Same debounce/dropdown shape as the domain-search box earlier in this same
 * wizard (a 400ms timer + a `results`/`searching` pair), reused rather than
 * reinvented for a second free-text field.
 */

import { useEffect, useRef, useState } from "react";

export type AddressSuggestion = {
  formatted: string;
  address1: string;
  city: string;
  stateProvince: string;
  postalCode: string;
  country: string;
};

export function AddressAutocompleteInput({
  value,
  onChangeText,
  onSelect,
  countryBias,
  maxLength,
  placeholder,
}: {
  value: string;
  onChangeText: (v: string) => void;
  onSelect: (s: AddressSuggestion) => void;
  /** ISO-3166 alpha-2 — biases (never filters) results toward this country. */
  countryBias?: string;
  maxLength?: number;
  placeholder?: string;
}) {
  const [results, setResults] = useState<AddressSuggestion[] | null>(null);
  const [searching, setSearching] = useState(false);
  const [open, setOpen] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const boxRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (timer.current) clearTimeout(timer.current);
    const q = value.trim();
    if (q.length < 4) {
      setResults(null);
      setSearching(false);
      return;
    }
    setSearching(true);
    timer.current = setTimeout(async () => {
      try {
        const params = new URLSearchParams({ q });
        if (countryBias) params.set("country", countryBias);
        const res = await fetch(`/api/geoapify/autocomplete?${params.toString()}`, { cache: "no-store" });
        const json: { results?: AddressSuggestion[] } = await res.json();
        setResults(json.results ?? []);
        setOpen(true);
      } catch {
        setResults([]);
      }
      setSearching(false);
    }, 400);
    return () => {
      if (timer.current) clearTimeout(timer.current);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [value, countryBias]);

  useEffect(() => {
    function onDocClick(e: MouseEvent) {
      if (boxRef.current && !boxRef.current.contains(e.target as Node)) setOpen(false);
    }
    document.addEventListener("mousedown", onDocClick);

